      licenseUrl: "https://creativecommons.org/share-your-work/public-domain/pdm/",
      attribution: "Dedication portrait of José Celestino Mutis from A. von Humboldt and A. Bonpland, stipple engraving, engraver and date not recorded, Wellcome Collection, public domain",
      attributionUrl: "https://wellcomecollection.org/works/xcte87qr",
      kind: "historical_depiction",
      
